def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]

    def orbit(r, c):
        seen = {(r, c)}
        todo = [(r, c)]
        while todo:
            i, j = todo.pop()
            candidates = [(j, i)]
            if 31 - i < n:
                candidates.append((31 - i, j))
            if 31 - j < n:
                candidates.append((i, 31 - j))
            if 31 - i < n and 31 - j < n:
                candidates.append((31 - j, 31 - i))
            for p in candidates:
                if p not in seen:
                    seen.add(p)
                    todo.append(p)
        return seen

    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] == 6:
                for i, j in orbit(r, c):
                    if grid[i][j] != 6:
                        out[r][c] = grid[i][j]
                        break
    return out

def transform(grid):
    n = len(grid[0])
    center = grid[0].index(2)
    out = [[0] * n for _ in range(n)]

    for r in range(n):
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2

        if r >= 3:
            for c in range(n):
                d = c - center
                if abs(d) <= r - 2 and (d - r) % 4 == 0 and out[r][c] == 0:
                    out[r][c] = 1

    return out

