def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def bands(n, active):
        result = []
        start = None
        for i in range(n):
            if active(i):
                if start is None:
                    start = i
            elif start is not None:
                result.append((start, i - 1))
                start = None
        if start is not None:
            result.append((start, n - 1))
        return result

    rb = bands(h, lambda r: any(grid[r][c] != 0 for c in range(w)))
    cb = bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))

    # The inset area of each repeated tile carries its identifying color.
    vals = {}
    counts = {}
    for i, (r0, r1) in enumerate(rb):
        for j, (c0, c1) in enumerate(cb):
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            colors = [grid[r][c]
                      for r in range(r0 + 1, r1)
                      for c in range(c0 + 1, c1)
                      if grid[r][c] != 0]
            if not colors:
                continue
            color = max(set(colors), key=colors.count)
            vals[i, j] = color
            counts[color] = counts.get(color, 0) + 1

    if not counts:
        return out
    base = max(counts, key=counts.get)

    # Continue each non-base color through the blank lanes between aligned tiles.
    for (i, j), color in vals.items():
        if color == base:
            continue
        r0, r1 = rb[i]
        c0, c1 = cb[j]

        for jj in range(j + 1, len(cb)):
            if vals.get((i, jj)) == color:
                for gap_col in range(cb[jj - 1][1] + 1, cb[jj][0]):
                    for r in range(r0 + 1, r1):
                        if out[r][gap_col] == 0:
                            out[r][gap_col] = color

        for ii in range(i + 1, len(rb)):
            if vals.get((ii, j)) == color:
                for gap_row in range(rb[ii - 1][1] + 1, rb[ii][0]):
                    for c in range(c0 + 1, c1):
                        if out[gap_row][c] == 0:
                            out[gap_row][c] = color

    return out

