def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    stack = [(r, c) for r in range(h) for c in range(w)
             if (r == 0 or r == h-1 or c == 0 or c == w-1) and grid[r][c] != wall]
    while stack:
        r, c = stack.pop()
        if (r, c) in seen or grid[r][c] == wall:
            continue
        seen.add((r, c))
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen:
                stack.append((nr,nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall and (r,c) not in seen:
                out[r][c] = 4
    return out

def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    outside = set()
    q = deque()

    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] == background:
                outside.add((r, c))
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and
                        grid[nr][nc] == background and (nr, nc) not in outside):
                    outside.add((nr, nc))
                    q.append((nr, nc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in outside:
                out[r][c] = 4
    return out

def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            touches_edge = False
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                if x == 0 or x == h - 1 or y == 0 or y == w - 1:
                    touches_edge = True
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == bg and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))

            if touches_edge or len(cells) > 9:
                continue
            minr = min(x for x, y in cells)
            maxr = max(x for x, y in cells)
            minc = min(y for x, y in cells)
            maxc = max(y for x, y in cells)
            if len(cells) == (maxr - minr + 1) * (maxc - minc + 1):
                for x, y in cells:
                    out[x][y] = 4

    return out

