def transform(grid):
    h, w = len(grid), len(grid[0])

    # Infer the cyclic color successor from non-repeated horizontal neighbors.
    counts = {}
    for row in grid:
        for a, b in zip(row, row[1:]):
            if a and b and a != b:
                counts.setdefault(a, {})
                counts[a][b] = counts[a].get(b, 0) + 1
    nxt = {a: max(opts, key=opts.get) for a, opts in counts.items()}

    def advance(x):
        return nxt.get(x, x)

    # Reconstruct the unshifted top-row pattern where it is obscured.
    base = list(grid[0])
    known = [i for i, x in enumerate(base) if x]
    if known:
        first = known[0]
        for c in range(first + 1, w):
            if not base[c]:
                base[c] = advance(base[c - 1])
        # Fill any leading gaps by walking backward through the successor cycle.
        pred = {v: k for k, v in nxt.items()}
        for c in range(first - 1, -1, -1):
            base[c] = pred.get(base[c + 1], base[c + 1])

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            value = base[c]
            if c < r:
                value = advance(value)
            row.append(value)
        out.append(row)
    return out

def transform(grid):
    n = len(grid)
    m = len(grid[0])

    def tile(flip_vertical, flip_horizontal):
        return [
            [grid[n - 1 - r if flip_vertical else r][m - 1 - c if flip_horizontal else c]
             for c in range(m)]
            for r in range(n)
        ]

    tiles = [
        [tile(True, True), tile(True, False), tile(True, True)],
        [tile(False, True), tile(False, False), tile(False, True)],
        [tile(True, True), tile(True, False), tile(True, True)],
    ]

    return [
        [value for block in tile_row for value in block[r]]
        for tile_row in tiles
        for r in range(n)
    ]

