def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid separator row or column.
    separator = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            separator = ("row", r)
            break
    if separator is None:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)):
                separator = ("col", c)
                break

    direction, index = separator
    if direction == "row":
