        ]

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The three colored cells across the top define left, center, and right rays.
    top = [(c, grid[0][c]) for c in range(w) if grid[0][c] != 0]
    if len(top) != 3:
        return out

    for side, (col, color) in enumerate(top):
        if side == 1:  # Center ray extends to the bottom.
            for r in range(h):
                out[r][col] = color
            continue

        # Find the matching marker away from the top row.
        marker = next(
            ((r, c) for r in range(1, h) for c in range(w)
             if grid[r][c] == color),
            None
        )
        if marker is None:
            continue

        r, c = marker
        for rr in range(min(r, h - 1) + 1):
            out[rr][col] = color
        for cc in range(min(col, c), max(col, c) + 1):
            out[r][cc] = color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform rows and columns are the separators.
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    row_bands = []
    start = 0
    for r in sorted(sep_rows):
        if start < r:
            row_bands.append((start, r))
        start = r + 1
    if start < h:
        row_bands.append((start, h))

    col_bands = []
    start = 0
    for c in sorted(sep_cols):
        if start < c:
            col_bands.append((start, c))
        start = c + 1
    if start < w:
        col_bands.append((start, w))

    # The background is the most frequent non-separator color.
    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors.update(grid[0][c] for c in sep_cols)
    counts = {}
    for r in range(h):
        if r in sep_rows:
            continue
        for c in range(w):
            if c not in sep_cols and grid[r][c] not in separator_colors:
                color = grid[r][c]
                counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    result = []
    for r0, r1 in row_bands:
        row = []
        for c0, c1 in col_bands:
            unusual = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if unusual == 2 else background)
        result.append(row)
    return result

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the centers of the 2-colored diamond shapes.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 2 and grid[r - 1][c] == 2 and
                grid[r + 1][c] == 2 and grid[r][c - 1] == 2 and
                grid[r][c + 1] == 2):
                centers.append((r, c))

    # Connect consecutive diamonds sharing a row or column.
    for r in range(h):
        row_centers = sorted(c for rr, c in centers if rr == r)
        for a, b in zip(row_centers, row_centers[1:]):
            for c in range(a + 2, b - 1):
                out[r][c] = 1

    for c in range(w):
        col_centers = sorted(r for r, cc in centers if cc == c)
        for a, b in zip(col_centers, col_centers[1:]):
            for r in range(a + 2, b - 1):
                out[r][c] = 1

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    objects = []

    # Locate the 3x3 motifs: a 3 border with a 2 in the center.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[y][x] == 3
                   for y in range(r - 1, r + 2)
                   for x in range(c - 1, c + 2)
                   if (y, x) != (r, c)):
                objects.append((r, c))

    for r, c in objects:
        row_rail = sum(grid[r][x] == 2 for x in range(w))
        col_rail = sum(grid[y][c] == 2 for y in range(h))
        if col_rail >= row_rail:
            # A vertical rail produces a horizontal beam.
            for x in range(w):
                if out[r][x] == 0:
                    out[r][x] = 1
            # Intersections with other vertical rails form a 3x3 marker.
            rails = [x for x in range(w)
                     if sum(grid[y][x] == 2 for y in range(h)) >= h - 1]
            for x in rails:
                if x == c:
                    continue
                for y in range(max(0, r - 1), min(h, r + 2)):
                    for xx in range(max(0, x - 1), min(w, x + 2)):
                        if (y, xx) != (r, x) and out[y][xx] != 3:
                            out[y][xx] = 1
        else:
            # A horizontal rail produces a vertical beam.
            for y in range(h):
                if out[y][c] == 0:
                    out[y][c] = 1
            rails = [y for y in range(h)
                     if sum(grid[y][x] == 2 for x in range(w)) >= w - 1]
            for y in rails:
                if y == r:
                    continue
                for yy in range(max(0, y - 1), min(h, y + 2)):
                    for x in range(max(0, c - 1), min(w, c + 2)):
                        if (yy, x) != (y, c) and out[yy][x] != 3:
                            out[yy][x] = 1

    return out

def transform(grid):
    counts = {c: sum(row.count(c) for row in grid) for c in (1, 2, 3)}
    color = max(counts, key=counts.get)

    patterns = {
        1: [(0, 2), (1, 0), (1, 1), (2, 1)],
        2: [(1, 0), (1, 1), (1, 2)],
        3: [(0, 1), (0, 2), (1, 1), (2, 1)],
    }
    out = [[0] * 3 for _ in range(3)]
    for r, c in patterns[color]:
        out[r][c] = 8
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the color used for complete separator lines.
    row_lines = {}
    col_lines = {}
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            row_lines.setdefault(row[0], []).append(r)
    for c in range(w):
        v = grid[0][c]
        if v != 0 and all(grid[r][c] == v for r in range(h)):
            col_lines.setdefault(v, []).append(c)
    div = max(set(row_lines) & set(col_lines),
              key=lambda x: len(row_lines[x]) + len(col_lines[x]))

    rs, cs = row_lines[div], col_lines[div]
    row_bounds = [-1] + rs + [h]
    col_bounds = [-1] + cs + [w]
    bands = [(row_bounds[i] + 1, row_bounds[i + 1])
             for i in range(len(row_bounds) - 1)]
    panels = [(col_bounds[i] + 1, col_bounds[i + 1])
              for i in range(len(col_bounds) - 1)]

    # Identify the repeated seed colors in the leftmost panel of each band.
    seeds = []
    for r0, r1 in bands:
        counts = {}
        for r in range(r0, r1):
            for c in range(panels[0][0], panels[0][1]):
                v = grid[r][c]
                if v and v != div:
                    counts[v] = counts.get(v, 0) + 1
        seeds.append(max(counts, key=counts.get))

    # The template is the non-divider color with the greatest total count.
    counts = {}
    for row in grid:
        for v in row:
            if v and v != div:
                counts[v] = counts.get(v, 0) + 1
    template_color = max(counts, key=counts.get)

    # Record its shape relative to the panel containing it.
    shape = None
    for r0, r1 in bands:
        for c0, c1 in panels:
            pts = [(r-r0, c-c0) for r in range(r0, r1)
                   for c in range(c0, c1) if grid[r][c] == template_color]
            if pts:
                shape = pts
                break
        if shape:
            break

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(bands):
        for c0, c1 in panels:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in shape:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = seeds[i]
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # The full row is the floor; objects settle toward it.
    floor_row = next(
        (r for r, row in enumerate(grid)
         if row[0] != 0 and all(v == row[0] for v in row)),
        None
    )
    if floor_row is None:
        return [row[:] for row in grid]

    direction = 1 if floor_row == 0 else -1
    floor_color = grid[floor_row][0]
    occupied = {
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] != 0 and r != floor_row
    }

    # Find 4-connected, single-color objects.
    objects = []
    unseen = set(occupied)
    while unseen:
        start = unseen.pop()
        color = grid[start[0]][start[1]]
        stack = [start]
        cells = {start}
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                p = (nr, nc)
                if p in unseen and grid[nr][nc] == color:
                    unseen.remove(p)
                    cells.add(p)
                    stack.append(p)
        objects.append((color, cells))

    # Let objects nearest the floor settle first.
    if direction == 1:
        objects.sort(key=lambda obj: min(r for r, c in obj[1]))
    else:
        objects.sort(key=lambda obj: -max(r for r, c in obj[1]))

    settled = set()
    result = [[0] * w for _ in range(h)]
    for c in range(w):
        result[floor_row][c] = floor_color

    for color, cells in objects:
        while True:
            shifted = {(r + direction, c) for r, c in cells}
            if any(
                r < 0 or r >= h or c < 0 or c >= w
                or r == floor_row or (r, c) in settled
                for r, c in shifted
            ):
                break
            cells = shifted
        for r, c in cells:
            result[r][c] = color
            settled.add((r, c))

    return result

def transform(grid):
    R, C = len(grid), len(grid[0])
    cells = {(r, c) for r in range(R) for c in range(C) if grid[r][c] == 8}

    def pieces_at(cell, remaining):
        r, c = cell
        # Prefer 2x2 squares.
        sq = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
        if sq <= remaining:
            yield sq, 1
        # L triominoes, colored by their missing corner.
        for dr in (-1, 0):
            for dc in (-1, 0):
                block = {(r + dr + i, c + dc + j)
                         for i in range(2) for j in range(2)}
                if not block <= remaining:
                    continue
                if len(block) != 4:
                    continue
                for missing, color in [
                    ((0, 0), 2),  # missing top-left
                    ((1, 0), 3),  # missing bottom-left
                    ((0, 1), 4),  # missing top-right
                    ((1, 1), 2),  # missing bottom-right
                ]:
                    tri = block - {(r + dr + missing[0], c + dc + missing[1])}
                    if cell in tri and tri <= remaining:
                        yield tri, color

    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for shape, color in pieces_at(cell, remaining):
            tail = solve(remaining - shape)
            if tail is not None:
                return [(shape, color)] + tail
        return None

    tiling = solve(cells)
