        cells = {(r, c) for r, c in points if grid[r][c] == color}
        while cells:
            start = cells.pop()
            comp = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for dr in (-1, 1):
                    for dc in (-1, 1):
                        q = (r + dr, c + dc)
                        if q in cells:
                            cells.remove(q)
                            comp.add(q)
                            stack.append(q)

            if len(comp) < 2:
                continue

            ends = []
            for r, c in comp:
                neighbors = [(r + dr, c + dc)
                             for dr in (-1, 1) for dc in (-1, 1)
                             if (r + dr, c + dc) in comp]
                if len(neighbors) == 1:
