        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                yield nr, nc

    while q:
        r, c = q.popleft()
        for nr, nc in neighbors(r, c):
            if grid[nr][nc] == 0 and (nr, nc) not in exterior:
                exterior.add((nr, nc))
                q.append((nr, nc))

