            comp = set()
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                cr, cc = stack.pop()
                comp.add((cr, cc))
                for nr, nc in neighbors(cr, cc):
                    if grid[nr][nc] == 1 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if any((nr, nc) in interior for cr, cc in comp
                   for nr, nc in neighbors(cr, cc)):
                marked_ones.update(comp)

