        border = {
            (r, c)
            for r in range(r0, r1 + 1)
            for c in range(c0, c1 + 1)
            if r in (r0, r1) or c in (c0, c1)
        }
        if all(grid[r][c] == color for r, c in border):
            if all(grid[r][c] == 0
                   for r in range(r0 + 1, r1)
                   for c in range(c0 + 1, c1)):
                frames.append((r0, r1, c0, c1, color))
                frame_cells.update(border)

    counts = {}
    for color, cells in positions.items():
        counts[color] = sum((r, c) not in frame_cells for r, c in cells)

    out = [[0] * w for _ in range(h)]
    for r0, r1, c0, c1, color in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color

    used = set()
    for r0, r1, c0, c1, _ in frames:
        ir0, ir1, ic0, ic1 = r0 + 1, r1 - 1, c0 + 1, c1 - 1
        target = sum(1 for r in range(ir0, ir1 + 1)
                     for c in range(ic0, ic1 + 1)
                     if (r - ir0 + c - ic0) % 2 == 0)
        choices = [(abs(n - target), color) for color, n in counts.items()
                   if color not in used and n > 0 and color not in
                   [f[4] for f in frames]]
        if not choices:
            continue
        _, fill = min(choices)
        used.add(fill)
        for r in range(ir0, ir1 + 1):
            for c in range(ic0, ic1 + 1):
                if (r - ir0 + c - ic0) % 2 == 0:
                    out[r][c] = fill
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full-width or full-height divider.
    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            divider = ('h', r, grid[r][0])
            break
    if divider is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1:
                divider = ('v', c, grid[0][c])
                break
    if divider is None:
        return [row[:] for row in grid]

    axis, pos, line_color = divider
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    colors = {v for row in grid for v in row if v not in (bg, line_color)}
    if not colors:
        return [row[:] for row in grid]
    obj_color = max(colors, key=lambda x: sum(row.count(x) for row in grid))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj_color]
    out = [row[:] for row in grid]
    for r, c in cells:
        out[r][c] = bg

    if axis == 'h':
        minr, maxr = min(r for r, c in cells), max(r for r, c in cells)
        if minr > pos:
            shift = pos + 1 - minr
            new_min, new_max = minr + shift, maxr + shift
        else:
            shift = pos - 1 - maxr
            new_min, new_max = minr + shift, maxr + shift
        for r, c in cells:
            out[r + shift][c] = obj_color
        mark = new_min - 1 if new_min > pos else new_max + 1
        if 0 <= mark < h:
            out[mark] = [8] * w
    else:
        minc, maxc = min(c for r, c in cells), max(c for r, c in cells)
        if minc > pos:
            shift = pos + 1 - minc
            new_min, new_max = minc + shift, maxc + shift
        else:
            shift = pos - 1 - maxc
            new_min, new_max = minc + shift, maxc + shift
        for r, c in cells:
            out[r][c + shift] = obj_color
        mark = new_min - 1 if new_min > pos else new_max + 1
        if 0 <= mark < w:
            for r in range(h):
                out[r][mark] = 8

    return out
